import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DE5v7xUD.js";var i=JSON.parse(`{"title":"CLI Command and Error Contract","description":"","frontmatter":{"id":"policy.0001","title":"CLI Command and Error Contract","status":"active","established-by":"proposal.0003","supersedes":[]},"headers":[],"relativePath":"policies/0001-cli-command-and-error-contract.md","filePath":"policies/0001-cli-command-and-error-contract.md"}`),a={name:`policies/0001-cli-command-and-error-contract.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="cli-command-and-error-contract" tabindex="-1">CLI Command and Error Contract <a class="header-anchor" href="#cli-command-and-error-contract" aria-label="Permalink to “CLI Command and Error Contract”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Recon&#39;s command discovery and failure classifications must describe the executable an agent is running. The command registry and typed failures protect that contract as commands are added.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>Define every Recon command in the command registry, and report every failure with a code from the published error enumeration.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to “Why this exists”">​</a></h2><p>A separately maintained usage string can advertise grammar the parser does not accept. Unclassified error strings make callers infer recovery from English. One registry supplies parsing, help, and command specifications; typed error codes supply machine-readable failure classification.</p><h2 id="what-it-applies-to" tabindex="-1">What it applies to <a class="header-anchor" href="#what-it-applies-to" aria-label="Permalink to “What it applies to”">​</a></h2><ul><li>Applies to: all existing and future Recon commands, including <code>schema</code> and <code>context</code>, and failures reported by the re-executing parent.</li><li>Does not apply to: test probe executables or failures emitted by the operating system outside Recon&#39;s control. The output-delivery boundaries in <a href="./../proposals/0003-agent-facing-cli-contract#errors">proposal 0003</a> still apply when a sink fails.</li></ul><p>Adding an error code is an ordinary contract change. Removing or renaming one changes the published contract and must be treated accordingly.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Tier: check (Tier 0), with structural enforcement in the implementation.</li><li>Mechanism: <code>crates/recon/src/cli/registry.rs</code> supplies the parser, help, and schema metadata. <code>Failure</code> requires an <code>ErrorCode</code>; schema generation publishes the enumeration. <code>crates/recon/tests/cli_contract.rs</code> checks registry discovery, parser constraints, and declared error-code coverage. <code>crates/recon/tests/cli_schema.rs</code>, the shared error-validation helpers, and the opt-in observation tests validate actual response and error envelopes against their advertised schemas. CI runs the crate checks through <code>mise run check</code>.</li></ul><p>These mechanisms enforce the rule; this record identifies the contract they protect without introducing a second command or error catalogue.</p><h2 id="how-to-comply" tabindex="-1">How to comply <a class="header-anchor" href="#how-to-comply" aria-label="Permalink to “How to comply”">​</a></h2><ol><li>Add or change commands through the existing registry and native typed parsers. Derive help and command metadata from that same source.</li><li>Represent failures with the existing typed error contract and declare each command&#39;s possible codes. Keep the serialization schemas and behavioral coverage aligned.</li><li>Run <code>mise run check</code>. For a changed permission-gated observation path, also exercise the existing signed UI checks with the required grants. Revise proposal intent before changing the public contract.</li></ol><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Proposal</th></tr></thead><tbody><tr><td>2026-10-27</td><td>Established the approved registry and published-error-code rule at completion.</td><td>proposal.0003</td></tr></tbody></table>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};